/// <summary>
/// PricingAttribute of table <c>EcoResProductVariantStyle</c> field Style.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(EcoResStyle, Name))]
internal class GUPPricingAttributeEcoResProductVariantStyleStyle extends GUPPricingAttributeEcoResProductVariantStyle
    implements GUPIPricingAttribute, GUPIPricingAttributeEcoResProductVariantDimensionValue
{
}

Method.Source:
public anytype getValueOfAttribute(Common _pricingObject)
{
    RefRecId styleId = this.getTableRecord(_pricingObject).Style;
    return EcoResStyle::find(styleId).Name;
}

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        QueryBuildDataSource qbdsStyle = _qbds.addDataSource(tableNum(EcoResStyle));
        qbdsStyle.joinMode(JoinMode::InnerJoin);
        qbdsStyle.addLink(fieldNum(EcoResProductVariantStyle, Style), fieldNum(EcoResStyle, RecId));
        qbdsStyle.addRange(fieldNum(EcoResStyle, Name)).value(queryValue(_value));
    }

    public void buildEcoResProductVariantQuery(Query _query, anytype _value, QueryBuildDataSource _qbds)
    {
        if (_qbds.table() != tableNum(EcoResDistinctProductVariant))
        {
            return;
        }

        QueryBuildDataSource qbdsVariantStyle, qbdsStyle;
        qbdsVariantStyle = _qbds.addDataSource(tableNum(EcoResProductVariantStyle));
        qbdsVariantStyle.joinMode(JoinMode::ExistsJoin);
        qbdsVariantStyle.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantStyle, DistinctProductVariant));

        qbdsStyle = qbdsVariantStyle.addDataSource(tableNum(EcoResStyle));
        qbdsStyle.joinMode(JoinMode::InnerJoin);
        qbdsStyle.addLink(fieldNum(EcoResProductVariantStyle,Style), fieldNum(EcoResStyle, RecId));

        qbdsStyle.addRange(fieldNum(EcoResStyle, Name)).value(queryValue(_value));
    }
